def _ohlcv_signature(payload: dict) -> tuple[Any, ...]:
    candles = payload.get("candles") or []
    last = candles[-1] if candles else {}
    return (
        payload.get("data_status"),
        len(candles),
        last.get("time") or last.get("timestamp"),
        last.get("open"),
        last.get("high"),
        last.get("low"),
        last.get("close"),
        last.get("volume"),
